def count_distinct_prime_factors(n):
    count = 0
    x = n
    p = 2
    while p * p <= x:
        if x % p == 0:
            count += 1
            while x % p == 0:
                x //= p
        p += 1
    if x > 1:
        count += 1
    return count

def remove_every_kth_1indexed(lst, k):
