    return [x for idx, x in enumerate(lst, start=1) if idx % k != 0]

def is_sorted_rotation_of_sorted(nums):
    n = len(nums)
    if n <= 1:
        return True
    drops = 0
    for i in range(n):
        if nums[i] > nums[(i + 1) % n]:
            drops += 1
    return drops <= 1

def sanitize_filename_windows(name):
    reserved = '<>:"/\\|?*'
    cleaned = "".join("_" if c in reserved else c for c in name)
