        return False
    return sum(d for d in range(1, n) if n % d == 0) == n

def compress_repeated_chars(s):
    if not s:
        return ""
    result = []
    prev = s[0]
    count = 1
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append(prev + str(count))
            prev = c
            count = 1
    result.append(prev + str(count))
    return ''.join(result)

def count_perfect_numbers_in_range(a, b):
    def proper_sum(x):
        if x <= 1:
            return 0
        total = 1
        i = 2
        while i * i <= x:
            if x % i == 0:
                total += i
                if i != x // i:
                    total += x // i
            i += 1
        return total
    count = 0
    for x in range(max(a, 1), b + 1):
        if x > 1 and proper_sum(x) == x:
            count += 1
    return count

def can_form_palindrome(s):
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1
    odd = sum(1 for c in freq.values() if c % 2 == 1)
    return odd <= 1

def alternate_upper_lower(s):
    result = []
    letter_idx = 0
    for c in s:
        if c.isalpha():
            result.append(c.upper() if letter_idx % 2 == 0 else c.lower())
            letter_idx += 1
        else:
            result.append(c)
    return "".join(result)

