def is_valid_relative_path(s):
    if not s or s.startswith('/') or s.endswith('/'):
        return False
    segments = s.split('/')
    for seg in segments:
        if not seg or seg in ('.', '..'):
            return False
        if not all(c.isalnum() or c in '_-.' for c in seg):
            return False
    return True

