def longest_increasing_run_start(lst):
    if not lst:
        return -1
    best_len = 1
    best_start = 0
    cur_len = 1
    cur_start = 0
    for i in range(1, len(lst)):
        if lst[i] > lst[i - 1]:
            cur_len += 1
        else:
            cur_start = i
            cur_len = 1
        if cur_len > best_len:
            best_len = cur_len
            best_start = cur_start
    return best_start

def rot13(s):
    out = []
    for ch in s:
        if ch.isalpha():
            base = 65 if ch.isupper() else 97
            out.append(chr((ord(ch) - base + 13) % 26 + base))
        else:
            out.append(ch)
    return ''.join(out)

def shift_and_fill(lst, k, fill):
    n = len(lst)
    if k >= n:
        return [fill] * n
    return [fill] * k + lst[:n - k]

